<?php
namespace App\Http\Controllers\Author;use App\Http\Controllers\Controller;use App\Models\Product;use App\Models\ProductVersion;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;
class ProductUpdateController extends Controller{public function store(Request $r,Product $product){abort_unless($product->author_id===Auth::id(),403);abort_unless($product->status==='published'||$product->status==='changes_requested',422,'Only published products can be updated.');$v=$r->validate(['change_summary'=>['required','string','max:5000'],'snapshot'=>['required','array'],'submit'=>['nullable','boolean']]);$latest=(int)$product->versions()->max('version_number');$version=ProductVersion::create(['product_id'=>$product->id,'version_number'=>$latest+1,'status'=>($v['submit']??false)?'pending':'draft','snapshot'=>$v['snapshot'],'change_summary'=>$v['change_summary'],'submitted_by'=>Auth::id(),'submitted_at'=>($v['submit']??false)?now():null]);return response()->json(['message'=>$version->status==='pending'?'Update submitted for review.':'Update draft saved.','version'=>$version],201);}public function submit(Product $product,ProductVersion $version){abort_unless($product->author_id===Auth::id()&&$version->product_id===$product->id,403);abort_unless(in_array($version->status,['draft','changes_requested'],true),422,'This update cannot be submitted.');$version->update(['status'=>'pending','submitted_at'=>now()]);return response()->json(['message'=>'Update submitted for review.']);}}